import '@servicenow/sdk/global'
import { StringColumn, IntegerColumn, BooleanColumn } from '@servicenow/sdk/core'
import { Subflow, wfa } from '@servicenow/sdk/automation'

/**
 * Test subflow for AssignSubflowOutputs with basic literal values
 */
export const assignSubflowOutputsBasic = Subflow(
    {
        $id: Now.ID['assign-subflow-outputs-basic'],
        name: 'AssignSubflowOutputs Basic Test',
        description: 'Test AssignSubflowOutputs with string, number, and boolean values',
        inputs: {
            inputData: StringColumn({
                label: 'Input Data',
                mandatory: true,
            }),
        },
        outputs: {
            result: StringColumn({
                label: 'Result',
                mandatory: true,
            }),
            totalCount: IntegerColumn({
                label: 'Total Count',
                mandatory: true,
            }),
            isComplete: BooleanColumn({
                label: 'Is Complete',
                mandatory: true,
            }),
        },
    },
    (params) => {
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-basic-instance'],
                annotation: 'Assign basic subflow outputs',
            },
            params.outputs,
            {
                result: 'success',
                totalCount: 100,
                isComplete: true,
            }
        )
    }
)
